# Define the function signatures
# gsl_factorize: takes an integer n and returns a list of factors
# prime_factors: takes an integer num and returns a list of factors

gsl.gsl_factorize.argtypes = [ctypes.c_int]
gsl.gsl_factorize.restype = ctypes.POINTER(ctypes.c_int)

def gsl_factorize(n):
    factors = gsl.gsl_factorize(n)
    if factors:
        return [factors[i] for i in range(ctypes.c_int(ctypes.c_int(0).value).value)]
    else:
        return []

# prime_factors is a helper function to get the factors

def prime_factors(num):
    if num <= 1:
        return []
    factors = []
    i = 2
    while i * i <= num:
        while num % i == 0:
            factors.append(i)
            num //= i
        i += 1
    if num > 1:
        factors.append(num)
    return factors

if __name__ == "__main__":
    n = int(input("Enter a positive integer: "))
    if n <= 0:
        print("Please enter a positive integer.")
    else:
        factors = gsl_factorize(n)
        print(f"Factors: {factors}")
        print(f"Number of factors: {len(factors)}")"}

