def cholesky_decomposition(input_matrix):
    # Convert input matrix to GSL matrix
    rows = len(input_matrix)
    cols = len(input_matrix[0])
    gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix, i, j, input_matrix[i][j])

    # Allocate permutation
    perm = gsl.gsl_permutation_alloc(rows)

    # Call GSL function
    status = gsl.gsl_linalg_pcholesky_decomp(gsl_matrix, perm)

    # Check for success
    if status != 0:
        raise ValueError("Matrix is not positive definite")

    # Extract permutation
    permutation = [gsl.gsl_permutation_get(perm, i) for i in range(rows)]

    # Extract lower matrix
    lower = [[0.0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(i+1):
            lower[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)

    # Extract diagonal
    diagonal = [0.0 for _ in range(rows)]
    for i in range(rows):
        diagonal[i] = gsl.gsl_matrix_get(gsl_matrix, i, i)

    # Extract upper matrix
    upper = [[0.0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
