import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix, dtype=np.float64, order='F')
        self.size = len(matrix)

    def is_positive_definite(self):
        # Load GSL libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function prototypes
        gsl.gsl_blas_dpotrf = ctypes.CFUNCTYPE(ctypes.c_int)("gsl_blas_dpotrf")
        gsl.gsl_linalg_cholesky_decomp = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int))

        # Check if matrix is positive definite
        n = self.size
        a = (ctypes.c_double * (n*n))()
        ipiv = (ctypes.c_int * n)()

        for i in range(n):
            for j in range(n):
                a[i*n + j] = self.matrix[i][j]

        status = gsl.gsl_linalg_cholesky_decomp(n, a, n, ipiv, ipiv)
        if status != 0:
            return False
        return True

    def cholesky_decomp(self):
        # Load GSL libraries
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Define function prototypes
        gsl.gsl_blas_dpotrf = ctypes.CFUNCTYPE(ctypes.c_int)("gsl_blas_dpotrf")
        gsl.gsl_linalg_cholesky_decomp = ctypes.CFUNCTYPE(ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_int))

        n = self.size
        a = (ctypes.c_double * (n*n))()
        ipiv = (ctypes.c_int * n)()

        for i in range(n):
            for j in range(n):
                a[i*n + j] = self.matrix[i][j]

        status = gsl.gsl_linalg_cholesky_decomp(n, a, n, ipiv, ipiv)
        if status != 0:
            raise ValueError("Matrix is not positive definite")

        # Extract lower triangular matrix
        L = [[0.0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(i+1):
                L[i][j] = a[i*n + j]
        return L


def cholesky_decomposition(matrix):
    if not isinstance(matrix, list):
        raise ValueError("Input must be a list")
    if len(matrix) == 0:
        raise ValueError("Input matrix is empty")
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")

    gsl_matrix = GSLMatrix(matrix)
    if not gsl_matrix.is_positive_definite():
        raise ValueError("Matrix is not positive definite")

    return gsl_matrix.cholesky_decomp()

