        [arr[i].real for i in range(len(arr))] + [arr[i].imag for i in range(len(arr))]
    )

def perform_fft(in_array, n):
    # Convert input array to ctypes array
    in_array_ptr = complex_array_to_ctypes(in_array)

    # Allocate output array
    out_array = (ctypes.c_double * (2 * n)).__class__(
        [0.0 for _ in range(2 * n)]
    )

    # Call GSL FFT function
    gsl.gsl_fft_complex_forward(in_array_ptr, n, 0, out_array)

    # Convert output array back to Python complex array
    result = [
        complex(out_array[2*i], out_array[2*i+1]) 
        for i in range(n)
    ]
    return result

