class GSL_Histogram2D(ctypes.Structure):
    _fields_ = [
        ('data', ctypes.POINTER(ctypes.c_double)),
        ('xsize', ctypes.c_int),
        ('ysize', ctypes.c_int),
        ('xrange', ctypes.POINTER(ctypes.c_double)),
        ('yrange', ctypes.POINTER(ctypes.c_double)),
        ('bin', ctypes.POINTER(ctypes.c_double)),
    ]

def create_histogram2d(nx, ny, xrange, yrange):

    # Validate input
    if not isinstance(nx, int) or nx <= 0:
        raise ValueError("nx must be a positive integer")
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError("ny must be a positive integer")

    if not isinstance(xrange, list) or len(xrange) != nx + 1:
        raise ValueError("xrange must be a list of length nx + 1")
    if not isinstance(yrange, list) or len(yrange) != ny + 1:
        raise ValueError("yrange must be a list of length ny + 1")

    # Check if xrange is increasing
    for i in range(nx):
        if xrange[i] >= xrange[i+1]:
            raise ValueError("xrange must be strictly increasing")

    # Check if yrange is increasing
    for i in range(ny):
        if yrange[i] >= yrange[i+1]:
            raise ValueError("yrange must be strictly increasing")

    # Load libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Convert lists to ctypes arrays
    xrange_arr = ctypes.pointer(ctypes.c_double * (nx + 1))(np.array(xrange, dtype=np.float64))
    yrange_arr = ctypes.pointer(ctypes.c_double * (ny + 1))(np.array(yrange, dtype=np.float64))

    # Call the C function
    ptr = gsl.gsl_histogram2d_calloc_range(nx, ny, xrange_arr, yrange_arr)

    # Cast to GSL_Histogram2D structure
    return ctypes.cast(ptr, ctypes.POINTER(GSL_Histogram2D))

